from typing import List, Optional

def replace_missing_values(data: List[List[Optional[float]]]) -> List[List[float]]:
    # 计算每列的均值
    means = []
    for col_index in range(len(data[0])):
        column = [row[col_index] for row in data if row[col_index] is not None]
        if len(column) == 0:
            means.append(0)
        else:
            means.append(sum(column) / len(column))

    # 替换缺失值
    cleaned_data = []
    for row in data:
        new_row = []
        for i, value in enumerate(row):
            if value is None:
                new_row.append(means[i])
            else:
                new_row.append(value)
        cleaned_data.append(new_row)

    return cleaned_data

