def min_partition_difference(n, weights):
    total_sum = sum(weights)
    target = total_sum // 2
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    # Base case: zero sum is always possible with any subset
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if weights[i - 1] <= j:
